@dataclass(frozen=True)
class ResticRepo:
    """
    Where a repo is, and how to reach it.

    `rclone_program` is what makes restic inherit BOXYARD'S storage-location
    abstraction rather than replacing it with restic's own, much narrower, set
    of backends. It is `None` for a local path, which is what tests use.
    """

    url: str
    password: str
    cache_dir: Path
    rclone_program: str | None = None

    def base_args(self) -> list[str]:
        args = [get_restic_binary()]
        if self.rclone_program is not None:
            args += ["-o", f"rclone.program={self.rclone_program}"]
        return args + ["-r", self.url]

    def env(self) -> dict[str, str]:
        """
        The child environment. The password is passed HERE, fetched once per
        process by the caller.

        Not restic's `--password-command`: restic reruns it on every
        invocation, and `secret get` measured 0.77-1.51 s, so at one invocation
        per box that is minutes of 1Password round trips per pass for a value
        that does not change.
        """
        env = dict(os.environ)
        env["RESTIC_PASSWORD"] = self.password
        env["RESTIC_CACHE_DIR"] = str(self.cache_dir)
        # A password file or command inherited from the ambient environment
        # would silently win over what we just set.
        env.pop("RESTIC_PASSWORD_FILE", None)
        env.pop("RESTIC_PASSWORD_COMMAND", None)
        env.pop("RESTIC_REPOSITORY", None)
        env.pop("RESTIC_REPOSITORY_FILE", None)
        return env


def require_restic_available(config, what: str) -> None:
    """
    Refuse NOW if this machine cannot work a restic repository.

    `what` names the operation, so the message says what will not happen rather
    than only what is wrong.

    Both prerequisites are checked together because both are fatal in the same
    way and a person fixing one wants to know about the other in the same
    breath: the binary, and the repository password.

    THE SCAR: `boxyard include` on a converted box printed "Included box ..."
    on a machine with no `restic` binary at all, created nothing, and the
    failure surfaced several commands later -- by which time `sync` refused,
    `exclude` refused, and the machine was in a state no command could exit.
    A command that reports success and does nothing is worse than one that
    refuses, so anything that will need restic asks this BEFORE it acts or
    prints.
    """
    try:
        get_restic_binary()
    except ResticError as e:
        raise ResticError(f"Cannot {what}: {e}") from None
    try:
        resolve_restic_password(config)
    except ResticError as e:
        raise ResticError(f"Cannot {what}: {e}") from None


def rclone_program_for(rclone_config_path: "str | Path") -> str:
    """
    The `-o rclone.program` string that routes restic through boxyard's own
    rclone configuration.

    restic takes this as ONE string and re-parses it into argv, so the paths in
    it must be quoted rather than interpolated raw. Verified against restic
    directly: with an unquoted path containing a space it splits at the space
    and dies with `fork/exec /tmp/claude-1000/rp: no such file or directory`,
    and with the same path shlex-quoted it runs. So restic parses this
    shell-style, and `shlex.join` is the matching encoder -- not a workaround
    for it.

    Interpolating a path into a string that something else re-parses is the
    exact pattern the repo bans everywhere else, and it was live here. Today
    both paths happen to be boxyard-controlled and space-free, so this was
    latent rather than broken -- but `rclone_config_path` comes from user
    config, and a home directory with a space in it is ordinary on macOS.
    """
    import shlex

    from ._utils import get_rclone_binary

    return shlex.join([str(get_rclone_binary()), "--config", str(rclone_config_path)])


def repo_url_for_box(
    store_path: Path, storage_location: str, remote_index_name: str
) -> str:
    """The rclone-backed repo URL for one box at one storage location."""
    path = (
        Path(store_path)
        / const.REMOTE_BOXES_REL_PATH
        / remote_index_name
        / const.BOX_RESTIC_REL_PATH
    )
    return f"rclone:{storage_location}:{path.as_posix()}"


def pointer_remote_path(store_path: Path, remote_index_name: str) -> Path:
    """Where the snapshot pointer lives on the remote, at depth 2."""
    return (
        Path(store_path)
        / const.REMOTE_BOXES_REL_PATH
        / remote_index_name
        / const.BOX_SNAPSHOT_POINTER_REL_PATH
    )

# %% pts/mod/_restic.pct.py 12
_password_cache: dict[str, str] = {}

# %% pts/mod/_restic.pct.py 13
def resolve_restic_password(config) -> str:
    """
    The repository password, from the environment or `restic_password_command`.

    Cached per resolved command for the life of the process, which is the whole
    point: `secret get` measured 0.77-1.51 s, and a 590-box pass would otherwise
    spend minutes on 1Password round trips for a value that cannot change.

    Refuses loudly when neither source is configured. There is no default and no
    fallback: an empty password would create a repository nobody could open
    again, and restic itself refuses one.
    """
    import subprocess

    env_value = os.environ.get(const.ENV_VAR_BOXYARD_RESTIC_PASSWORD)
    if env_value:
        return env_value

    command = getattr(config, "restic_password_command", None)
    if not command:
        raise ResticError(
            f"No restic repository password is configured. Set "
            f"`restic_password_command` in '{config.config_path}' to a command "
            f"that prints it (e.g. `secret get BOXYARD_RESTIC_PASSWORD`), or "
            f"set ${const.ENV_VAR_BOXYARD_RESTIC_PASSWORD}."
        )
    if command in _password_cache:
        return _password_cache[command]

    # A configured command is a shell string by nature ("secret get NAME"), and
    # it comes from the user's own config file rather than from box content, so
    # `shell=True` is appropriate here and only here. Nothing derived from a
    # path or a box name is ever interpolated into it.
    proc = subprocess.run(
        command, shell=True, capture_output=True, text=True
    )
    if proc.returncode != 0:
        raise ResticError(
            f"`restic_password_command` failed (exit {proc.returncode}): "
            f"{command}\n{proc.stderr.strip()}"
        )
    password = proc.stdout.strip()
    if not password:
        raise ResticError(
            f"`restic_password_command` produced no output: {command}. An empty "
            f"password would create a repository that cannot be opened again."
        )
    _password_cache[command] = password
    return password

# %% pts/mod/_restic.pct.py 15
async def run_restic(
    repo: ResticRepo,
    args: list[str],
    *,
    timeout: float | None = None,
    check: bool = True,
    stdout_line_callback=None,
) -> tuple[int, str, str]:
    """
    Run one restic subcommand. Returns `(returncode, stdout, stderr)`.

    Always argv, never a shell string: a box's DATA path comes off the
    filesystem and may contain spaces, quotes, backticks or `$()`.

    `check=False` is for the callers that must distinguish "restic said no" from
    "restic failed" -- notably `snapshot_exists`, where restic's two relevant
    commands disagree about how absence is reported.
    """
    cmd = repo.base_args() + args
    returncode, stdout, stderr = await run_cmd_async(
        cmd,
        timeout=timeout,
        env=repo.env(),
        stdout_line_callback=stdout_line_callback,
    )
    if returncode == const.RESTIC_EXIT_LOCK_FAILED:
        raise ResticLocked(
            f"restic could not lock '{repo.url}': another operation holds it "
            f"exclusively (`forget` or `prune`, or a stale lock from a machine "
            f"that suspended). `restic unlock` clears a stale one.\n{stderr.strip()}",
            returncode=returncode,
            stderr=stderr,
        )
    if check and returncode != 0:
        raise ResticError(
            f"`restic {args[0] if args else ''}` failed on '{repo.url}' "
            f"(exit {returncode}).\n{stderr.strip()}",
            returncode=returncode,
            stderr=stderr,
        )
    return returncode, stdout, stderr


async def init_repo(repo: ResticRepo) -> None:
    """Create the repository. Fails loudly if one is already there."""
    await run_restic(repo, ["init"])


async def repo_exists(repo: ResticRepo) -> bool:
    """Whether a repository is already present and openable at this URL."""
    returncode, _, _ = await run_restic(
        repo, ["cat", "config"], timeout=const.RESTIC_METADATA_TIMEOUT, check=False
    )
    return returncode == 0

