class CanonicalRootUnavailable(Exception):
    """
    The canonical root cannot be used on this machine.

    Raised rather than worked around, because silently backing up through the
    real path instead would record a path no other machine can match, and the
    damage (every other machine falling back to full restores) would show up
    somewhere else entirely.
    """


def canonical_root() -> Path:
    """
    The fixed directory every box is backed up through, created 0700 and
    validated.

    `/tmp` is world-writable and sticky on every machine in this fleet, so a
    hostile or stale entry could otherwise redirect a backup -- or a restore --
    outside the box. The root must therefore be a real directory, not a symlink,
    owned by us, and not group- or world-writable. Anything else is refused.
    """
    root = Path(const.RESTIC_CANONICAL_ROOT)
    if root.is_symlink():
        raise CanonicalRootUnavailable(
            f"'{root}' is a symlink. It must be a real directory owned by this "
            f"user; refusing to back up through it."
        )
    try:
        root.mkdir(mode=0o700, parents=True, exist_ok=True)
    except OSError as exc:
        raise CanonicalRootUnavailable(
            f"cannot create the canonical restic root '{root}': {exc}"
        ) from exc
    stat = root.stat()
    if not root.is_dir():
        raise CanonicalRootUnavailable(f"'{root}' exists and is not a directory.")
    if hasattr(os, "geteuid") and stat.st_uid != os.geteuid():
        raise CanonicalRootUnavailable(
            f"'{root}' is owned by uid {stat.st_uid}, not by this user "
            f"({os.geteuid()}). Refusing to back up through it."
        )
    if stat.st_mode & 0o077:
        raise CanonicalRootUnavailable(
            f"'{root}' is mode {stat.st_mode & 0o777:o}; it must not be readable "
            f"or writable by group or other."
        )
    return root


def canonical_data_path(box_index_name: str) -> Path:
    """
    The path a box is ALWAYS backed up through, on every machine.

    Note the index name appears twice, and that is the point: the first is the
    symlink (pointing at this machine's checkout root), the second is the box's
    own directory inside it. A symlink as the FINAL component would archive the
    link and nothing else.
    """
    return Path(const.RESTIC_CANONICAL_ROOT) / box_index_name / box_index_name


@contextlib.contextmanager
def canonical_link(box_index_name: str, data_path: Path):
    """
    Point the canonical path at `data_path` for the duration of one operation.

    Re-pointed ATOMICALLY on every use, never created-only-if-missing: a crashed
    run can leave a link aimed at a checkout root the box has since left, and
    silently backing up the old location would be worse than any failure. Costs
    0.033 ms, measured.
    """
    data_path = Path(data_path).resolve()
    if data_path.name != box_index_name:
        raise CanonicalRootUnavailable(
            f"'{data_path}' is not named for its box ('{box_index_name}'), so the "
            f"canonical path cannot be formed. This is a boxyard bug, not a "
            f"user error."
        )
    root = canonical_root()
    link = root / box_index_name
    tmp = root / f".tmp-{box_index_name}-{os.getpid()}"
    tmp.unlink(missing_ok=True)
    os.symlink(data_path.parent, tmp)
    os.replace(tmp, link)
    try:
        yield canonical_data_path(box_index_name)
    finally:
        link.unlink(missing_ok=True)

# %% pts/mod/_restic.pct.py 19
def data_root_exclude_args(data_path: Path) -> list[str]:
    """
    `--exclude` arguments for things that must never enter a snapshot.

    Today that is exactly the exec-bit manifest: restic carries Unix mode
    natively and exactly (755/644/775 all round-trip), so the manifest is dead
    weight for a restic-backed box -- and leaving it in would churn a generated
    file inside the very thing that exists to avoid churning generated files.

    ANCHORED TO THE ABSOLUTE PATH, because that is what `backup` matches
    against. The bare basename would also exclude a `.boxyard-perms.json` that
    is real content somewhere inside the box; a leading slash would exclude
    nothing at all.
    """
    return [
        "--exclude",
        (Path(data_path) / const.BOX_PERMS_MANIFEST_REL_PATH).as_posix(),
    ]


def restic_excludes_from_rclone_file(exclude_path: "str | Path | None") -> list[str]:
    """
    Translate boxyard's rclone exclude file into restic `--exclude` patterns.

    Without this a converted box would silently start storing `.venv/`,
    `node_modules/`, `target/` and everything else the fleet-wide exclude list
    removes -- the same list that cut jackfruit from 687,876 files to 134,551
    before restic was involved at all. Ignoring it would not be a small
    regression.

    The two syntaxes agree on the case that matters. rclone writes one pattern
    per line with a trailing slash for a directory (".venv/"), and restic
    matches an unanchored pattern against the basename at any depth -- which is
    exactly rclone's meaning for these names. Only the trailing slash has to go.

    Deliberately NOT passed to restic as `--exclude-file`: the file is rclone's,
    the syntaxes diverge for anchored and wildcard patterns, and handing restic a
    file written for another tool would silently apply different rules than the
    plain path does.
    """
    if exclude_path is None:
        return []
    path = Path(exclude_path)
    if not path.is_file():
        return []
    patterns: list[str] = []
    for line in path.read_text().splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        patterns.append(stripped.rstrip("/"))
    return patterns


def anchored_include_args(rel_paths: list[str]) -> list[str]:
    """
    `--include` arguments for a targeted restore, anchored to the snapshot
    SUBPATH by a leading slash.

    Without the leading slash restic matches the basename at any depth, so
    restoring one changed `package.json` would restore every `package.json` in
    the box. With an absolute path it matches nothing and restores silently
    nothing at all.
    """
    args: list[str] = []
    for rel in rel_paths:
        args += [f"--include=/{rel.lstrip('/')}"]
    return args

